 restored:=&memoryEngine{};if err:=restored.open();err!=nil{t.Fatal(err)}
 if !reflect.DeepEqual(wantReport,restored.report(2)){t.Fatal("reported comment lost after moderation/recovery")}
 if !reflect.DeepEqual(wantStats,restored.streamStatistics(10)){t.Fatal("statistics not recovered")}
